func SetData(resource plugin.Resource, field string, val *llx.RawData) error {
	f, ok := setDataFields[resource.MqlName()+"."+field]
	if !ok {
		return errors.New("[consul] cannot set '" + field + "' in resource '" + resource.MqlName() + "', field not found")
	}

	if ok := f(resource, val); !ok {
		return errors.New("[consul] cannot set '" + field + "' in resource '" + resource.MqlName() + "', type does not match")
	}
	return nil
}

func SetAllData(resource plugin.Resource, args map[string]*llx.RawData) error {
	var err error
	for k, v := range args {
		if err = SetData(resource, k, v); err != nil {
			return err
		}
	}
	return nil
}

// mqlConsul for the consul resource
type mqlConsul struct {
	MqlRuntime *plugin.Runtime
	__id       string
	mqlConsulInternal
	Datacenter           plugin.TValue[string]
	PrimaryDatacenter    plugin.TValue[string]
	NodeName             plugin.TValue[string]
	NodeId               plugin.TValue[string]
	Version              plugin.TValue[string]
	Revision             plugin.TValue[string]
	BuildDate            plugin.TValue[*time.Time]
	Server               plugin.TValue[bool]
	GossipEncrypted      plugin.TValue[bool]
	WanGossipEncrypted   plugin.TValue[bool]
	VerifyIncoming       plugin.TValue[bool]
	VerifyOutgoing       plugin.TValue[bool]
	VerifyServerHostname plugin.TValue[bool]
	AutoEncryptTls       plugin.TValue[bool]
	AutoEncryptAllowTls  plugin.TValue[bool]
	TlsProfiles          plugin.TValue[[]any]
	Acl                  plugin.TValue[*mqlConsulAclSystem]
	Mesh                 plugin.TValue[*mqlConsulServiceMesh]
}

// createConsul creates a new instance of this resource
func createConsul(runtime *plugin.Runtime, args map[string]*llx.RawData) (plugin.Resource, error) {
	res := &mqlConsul{
		MqlRuntime: runtime,
	}

	err := SetAllData(res, args)
	if err != nil {
		return res, err
	}

	if res.__id == "" {
		res.__id, err = res.id()
		if err != nil {
			return nil, err
		}
	}

	if runtime.HasRecording {
		args, err = runtime.ResourceFromRecording("consul", res.__id)
		if err != nil || args == nil {
			return res, err
		}
		return res, SetAllData(res, args)
	}

	return res, nil
}

